<?php
require_once '../includes/auth.php'; requireActiveUser(); requireTenantContext(); requireModulePermission('network','view');
global $conn; $tenantId=(int)getCurrentTenantId(); $olts=[];$onus=[];
$q=$conn->prepare("SELECT * FROM olt_devices WHERE tenant_id=? ORDER BY id DESC"); if($q){$q->bind_param('i',$tenantId);$q->execute();$z=$q->get_result();while($r=$z->fetch_assoc())$olts[]=$r;$q->close();}
$q=$conn->prepare("SELECT o.*,l.name olt_name FROM onu_devices o LEFT JOIN olt_devices l ON l.id=o.olt_id AND l.tenant_id=o.tenant_id WHERE o.tenant_id=? ORDER BY o.id DESC LIMIT 300"); if($q){$q->bind_param('i',$tenantId);$q->execute();$z=$q->get_result();while($r=$z->fetch_assoc())$onus[]=$r;$q->close();}
$pageTitle='OLT & ONU Management'; require_once '../includes/header.php'; ?>
<div class="dashboard-card"><div class="page-header"><div><h2>OLT &amp; ONU Management</h2><p>Fiber access infrastructure, PON ports and subscriber ONUs.</p></div></div>
<div class="table-responsive"><table><thead><tr><th>OLT</th><th>Vendor</th><th>Host</th><th>Status</th><th>Last Seen</th></tr></thead><tbody><?php foreach($olts as $x):?><tr><td><?=e($x['name'])?></td><td><?=e($x['vendor']??'—')?></td><td><?=e($x['host']??'—')?></td><td><?=e($x['status'])?></td><td><?=e($x['last_seen_at']??'—')?></td></tr><?php endforeach;?><?php if(!$olts):?><tr><td colspan="5">No OLTs configured.</td></tr><?php endif;?></tbody></table></div>
<h3 style="margin-top:28px">ONUs</h3><div class="table-responsive"><table><thead><tr><th>Serial</th><th>OLT</th><th>PON</th><th>Customer</th><th>Status</th><th>RX/TX</th></tr></thead><tbody><?php foreach($onus as $x):?><tr><td><?=e($x['serial_number']??'—')?></td><td><?=e($x['olt_name']??'—')?></td><td><?=e($x['pon_port']??'—')?></td><td><?=e($x['customer_id']??'—')?></td><td><?=e($x['status'])?></td><td><?=e(($x['signal_rx']??'—').' / '.($x['signal_tx']??'—'))?></td></tr><?php endforeach;?><?php if(!$onus):?><tr><td colspan="6">No ONUs discovered or registered.</td></tr><?php endif;?></tbody></table></div></div><?php require_once '../includes/footer.php';?>